from __future__ import annotations

import datetime
from typing import Optional, Dict, List
from dataclasses import dataclass, field
import uuid

STATUSES = ("To Do", "In Progress", "Done")
PRIORITIES = ("Low", "Medium", "High")


class Task:
    def __init__(
        self,
        id: str,
        title: str,
        priority: str,
        description: Optional[str] = None,
        tags: Optional[list[str]] = None,
        due_date: Optional[datetime.date] = None,
        status: str = "To Do",
        dependencies: Optional[list[str]] = None,
    ) -> None:
        self.id: str = id
        self.title: str = title
        self.description: Optional[str] = description
        self.priority: str = priority
        self.tags: list[str] = list(tags) if tags else []
        self.due_date: Optional[datetime.date] = due_date
        self.status: str = status
        self.dependencies: list[str] = list(dependencies) if dependencies else []

    def to_dict(self) -> dict:
        return {
            "id": self.id,
            "title": self.title,
            "description": self.description,
            "priority": self.priority,
            "tags": list(self.tags),
            "due_date": self.due_date.isoformat() if self.due_date else None,
            "status": self.status,
            "dependencies": list(self.dependencies),
        }

    @classmethod
    def from_dict(cls, data: dict) -> "Task":
        due = data.get("due_date")
        due_date = datetime.date.fromisoformat(due) if due else None
        return cls(
            id=data["id"],
            title=data["title"],
            description=data.get("description"),
            priority=data["priority"],
            tags=data.get("tags") or [],
            due_date=due_date,
            status=data.get("status", "To Do"),
            dependencies=data.get("dependencies") or [],
        )


class Project:
    def __init__(self, id: str, name: str, tasks: Optional[dict[str, Task]] = None) -> None:
        self.id: str = id
        self.name: str = name
        self.tasks: dict[str, Task] = dict(tasks) if tasks else {}

    def add_task(self, task: Task) -> None:
        self.tasks[task.id] = task

    def remove_task(self, task_id: str) -> None:
        if task_id in self.tasks:
            del self.tasks[task_id]

    def find_dependents(self, task_id: str) -> list[Task]:
        dependents: list[Task] = []
        for t in self.tasks.values():
            if task_id in t.dependencies:
                dependents.append(t)
        return dependents

    def to_dict(self) -> dict:
        return {
            "id": self.id,
            "name": self.name,
            "tasks": {tid: t.to_dict() for tid, t in self.tasks.items()},
        }

    @classmethod
    def from_dict(cls, data: dict) -> "Project":
        tasks_dict = {tid: Task.from_dict(tdata) for tid, tdata in (data.get("tasks") or {}).items()}
        return cls(id=data["id"], name=data["name"], tasks=tasks_dict)


class AppState:
    def __init__(self, projects: Optional[dict[str, Project]] = None, active_project_id: Optional[str] = None) -> None:
        self.projects: dict[str, Project] = dict(projects) if projects else {}
        self.active_project_id: Optional[str] = active_project_id

    def get_active_project(self) -> Optional[Project]:
        if self.active_project_id and self.active_project_id in self.projects:
            return self.projects[self.active_project_id]
        return None

    def set_active_project(self, project_id: Optional[str]) -> None:
        self.active_project_id = project_id

    def to_dict(self) -> dict:
        return {
            "projects": {pid: proj.to_dict() for pid, proj in self.projects.items()},
            "active_project_id": self.active_project_id,
        }

    @classmethod
    def from_dict(cls, data: dict) -> "AppState":
        projects = {pid: Project.from_dict(pdata) for pid, pdata in (data.get("projects") or {}).items()}
        active = data.get("active_project_id")
        return cls(projects=projects, active_project_id=active)

from typing import Optional, List


class DependencyCycleError(Exception):
    def __init__(self, message: str) -> None:
        super().__init__(message)


class BlockedCompletionError(Exception):
    def __init__(self, message: str, blocking_dependencies: Optional[list[str]] = None) -> None:
        super().__init__(message)
        self.blocking_dependencies = list(blocking_dependencies) if blocking_dependencies else []


class DeletionBlockedError(Exception):
    def __init__(self, message: str, dependents: Optional[list[str]] = None) -> None:
        super().__init__(message)
        self.dependents = list(dependents) if dependents else []

import datetime
from typing import Optional


ALLOWED_PRIORITIES = {"Low", "Medium", "High"}


def validate_title(title: str) -> None:
    if title is None or not isinstance(title, str) or title.strip() == "":
        raise ValueError("Title must be non-empty.")


def validate_priority(value: str) -> None:
    if value not in ALLOWED_PRIORITIES:
        allowed = ", ".join(sorted(ALLOWED_PRIORITIES))
        raise ValueError(f"Priority must be one of: {allowed}")


def parse_due_date(due_date_str: str) -> datetime.date:
    try:
        return datetime.date.fromisoformat(due_date_str)
    except Exception:
        raise ValueError("Due date must be a valid ISO 8601 date (YYYY-MM-DD).")


def normalize_tags(tags: Optional[list[str]]) -> list[str]:
    if not tags:
        return []
    seen_lower = set()
    result: list[str] = []
    for t in tags:
        if t is None:
            continue
        s = str(t).strip()
        if s == "":
            continue
        low = s.lower()
        if low in seen_lower:
            continue
        seen_lower.add(low)
        result.append(s)
    return result

from __future__ import annotations

import uuid
from typing import Optional, List, Set

import datetime

import models
import persistence
import validation
from exceptions import DependencyCycleError, BlockedCompletionError, DeletionBlockedError


class ProjectService:
    def __init__(self, state: models.AppState, repo: persistence.JsonRepository) -> None:
        self.state = state
        self.repo = repo

    def create_project(self, name: str) -> models.Project:
        name_s = (name or "").strip()
        if not name_s:
            raise ValueError("Project name must be non-empty.")
        pid = str(uuid.uuid4())
        project = models.Project(id=pid, name=name_s)
        self.state.projects[pid] = project
        # Set active project to the new one
        self.state.active_project_id = pid
        self.repo.save_debounced(self.state)
        return project

    def list_projects(self) -> list[models.Project]:
        return list(self.state.projects.values())

    def set_active_project(self, project_id: str) -> models.Project:
        if project_id not in self.state.projects:
            raise KeyError("Project not found")
        self.state.set_active_project(project_id)
        self.repo.save_debounced(self.state)
        return self.state.projects[project_id]

    def rename_project(self, project_id: str, new_name: str) -> models.Project:
        if project_id not in self.state.projects:
            raise KeyError("Project not found")
        new_name_s = (new_name or "").strip()
        if not new_name_s:
            raise ValueError("Project name must be non-empty.")
        proj = self.state.projects[project_id]
        proj.name = new_name_s
        self.repo.save_debounced(self.state)
        return proj

    def delete_project(self, project_id: str) -> None:
        if project_id not in self.state.projects:
            raise KeyError("Project not found")
        del self.state.projects[project_id]
        if self.state.active_project_id == project_id:
            # Choose another project if available, else None
            self.state.active_project_id = next(iter(self.state.projects.keys()), None)
        self.repo.save_debounced(self.state)


class TaskService:
    def __init__(self, state: models.AppState, repo: persistence.JsonRepository) -> None:
        self.state = state
        self.repo = repo

    def _get_project(self, project_id: str) -> models.Project:
        if project_id not in self.state.projects:
            raise KeyError("Project not found")
        return self.state.projects[project_id]

    def list_tasks(self, project_id: str) -> list[models.Task]:
        proj = self._get_project(project_id)
        return list(proj.tasks.values())

    def get_task(self, project_id: str, task_id: str) -> models.Task:
        proj = self._get_project(project_id)
        if task_id not in proj.tasks:
            raise KeyError("Task not found")
        return proj.tasks[task_id]

    def create_task(
        self,
        project_id: str,
        title: str,
        priority: str,
        description: Optional[str] = None,
        tags: Optional[list[str]] = None,
        due_date: Optional[str] = None,
        status: Optional[str] = None,
        dependencies: Optional[list[str]] = None,
    ) -> models.Task:
        proj = self._get_project(project_id)
        validation.validate_title(title)
        validation.validate_priority(priority)
        tags_norm = validation.normalize_tags(tags)
        due: Optional[datetime.date] = None
        if due_date:
            due = validation.parse_due_date(due_date)
        st = status if status in models.STATUSES else "To Do"
        deps = list(dependencies) if dependencies else []
        # validate deps exist and no self-dependency
        for dep_id in deps:
            if dep_id not in proj.tasks:
                raise KeyError(f"Dependency task not found: {dep_id}")
        new_task_id = str(uuid.uuid4())
        if new_task_id in deps:
            raise DependencyCycleError("Task cannot depend on itself.")
        task = models.Task(
            id=new_task_id,
            title=title.strip(),
            description=description,
            priority=priority,
            tags=tags_norm,
            due_date=due,
            status=st,
            dependencies=deps,
        )
        # If creating as Done, ensure all deps are Done
        if task.status == "Done":
            blocking = [tid for tid in task.dependencies if proj.tasks.get(tid) and proj.tasks[tid].status != "Done"]
            if blocking:
                raise BlockedCompletionError("Cannot complete: dependencies incomplete", blocking_dependencies=blocking)
        # Check for cycles with the new task inserted
        if deps:
            self._assert_no_cycle_on_set(proj, task.id, deps, preexisting_task=task, include_new=True)
        proj.add_task(task)
        self.repo.save_debounced(self.state)
        return task

    def edit_task(
        self,
        project_id: str,
        task_id: str,
        *,
        title: Optional[str] = None,
        description: Optional[str] = None,
        priority: Optional[str] = None,
        tags: Optional[list[str]] = None,
        due_date: Optional[str] = None,
        due_date_set: bool = False,
        status: Optional[str] = None,
    ) -> models.Task:
        proj = self._get_project(project_id)
        task = self.get_task(project_id, task_id)

        if title is not None:
            validation.validate_title(title)
            task.title = title.strip()
        if description is not None:
            task.description = description
        if priority is not None:
            validation.validate_priority(priority)
            task.priority = priority
        if tags is not None:
            task.tags = validation.normalize_tags(tags)
        if due_date_set:
            if due_date:
                task.due_date = validation.parse_due_date(due_date)
            else:
                task.due_date = None
        if status is not None:
            self._set_status_with_gating(proj, task, status)

        self.repo.save_debounced(self.state)
        return task

    def set_task_status(self, project_id: str, task_id: str, new_status: str) -> models.Task:
        proj = self._get_project(project_id)
        task = self.get_task(project_id, task_id)
        self._set_status_with_gating(proj, task, new_status)
        self.repo.save_debounced(self.state)
        return task

    def move_task_between_columns(self, project_id: str, task_id: str, destination_status: str) -> models.Task:
        # Same as set status
        return self.set_task_status(project_id, task_id, destination_status)

    def delete_task(self, project_id: str, task_id: str) -> None:
        proj = self._get_project(project_id)
        if task_id not in proj.tasks:
            raise KeyError("Task not found")
        dependents = proj.find_dependents(task_id)
        if dependents:
            names = ", ".join(t.title for t in dependents)
            raise DeletionBlockedError(
                f"Cannot delete: other tasks depend on it ({names})",
                dependents=[t.id for t in dependents],
            )
        proj.remove_task(task_id)
        self.repo.save_debounced(self.state)

    def set_dependencies(self, project_id: str, task_id: str, predecessor_ids: list[str]) -> models.Task:
        proj = self._get_project(project_id)
        task = self.get_task(project_id, task_id)
        preds = list(predecessor_ids) if predecessor_ids else []
        if task_id in preds:
            raise DependencyCycleError("Task cannot depend on itself.")
        # validate existence
        for pid in preds:
            if pid not in proj.tasks:
                raise KeyError(f"Dependency task not found: {pid}")

        self._assert_no_cycle_on_set(proj, task_id, preds)
        # If task is Done, block if any preds not Done
        if task.status == "Done":
            blocking = [pid for pid in preds if proj.tasks[pid].status != "Done"]
            if blocking:
                raise BlockedCompletionError("Cannot complete: dependencies incomplete", blocking_dependencies=blocking)

        task.dependencies = preds
        self.repo.save_debounced(self.state)
        return task

    def add_tag(self, project_id: str, task_id: str, tag: str) -> models.Task:
        task = self.get_task(project_id, task_id)
        norm = validation.normalize_tags([tag])
        if not norm:
            return task
        val = norm[0]
        low = val.lower()
        if all(t.lower() != low for t in task.tags):
            task.tags.append(val)
            self.repo.save_debounced(self.state)
        return task

    def remove_tag(self, project_id: str, task_id: str, tag: str) -> models.Task:
        task = self.get_task(project_id, task_id)
        low = (tag or "").strip().lower()
        if not low:
            return task
        task.tags = [t for t in task.tags if t.lower() != low]
        self.repo.save_debounced(self.state)
        return task

    def _set_status_with_gating(self, proj: models.Project, task: models.Task, new_status: str) -> None:
        if new_status not in models.STATUSES:
            raise ValueError(f"Status must be one of: {', '.join(models.STATUSES)}")
        if new_status == "Done":
            blocking = [tid for tid in task.dependencies if proj.tasks.get(tid) and proj.tasks[tid].status != "Done"]
            if blocking:
                raise BlockedCompletionError("Cannot complete: dependencies incomplete", blocking_dependencies=blocking)
        task.status = new_status

    def _assert_no_cycle_on_set(
        self,
        proj: models.Project,
        task_id: str,
        new_predecessors: list[str],
        *,
        preexisting_task: Optional[models.Task] = None,
        include_new: bool = False,
    ) -> None:
        # Build adjacency: task -> predecessors
        adj: dict[str, list[str]] = {}
        for tid, t in proj.tasks.items():
            adj[tid] = list(t.dependencies)
        if preexisting_task is not None and include_new:
            adj[preexisting_task.id] = list(new_predecessors)
        else:
            adj[task_id] = list(new_predecessors)

        # Check for path from any new predecessor to task_id
        target = task_id

        def dfs(start: str, visited: set[str]) -> bool:
            if start == target:
                return True
            visited.add(start)
            for n in adj.get(start, []):
                if n in visited:
                    continue
                if dfs(n, visited):
                    return True
            return False

        for pred in new_predecessors:
            if dfs(pred, set()):
                raise DependencyCycleError("Circular dependency detected.")

from __future__ import annotations

from typing import Optional, Set

import models
from validation import parse_due_date


def filter_tasks(
    tasks: list[models.Task],
    status: Optional[set[str]] = None,
    priorities: Optional[set[str]] = None,
    tags_any_of: Optional[set[str]] = None,
    due_date_start: Optional[str] = None,
    due_date_end: Optional[str] = None,
) -> list[models.Task]:
    status_set = set(status) if status else None
    prio_set = set(priorities) if priorities else None
    tags_set = {t.lower() for t in tags_any_of} if tags_any_of else None

    start_date = parse_due_date(due_date_start) if due_date_start else None
    end_date = parse_due_date(due_date_end) if due_date_end else None

    def include(task: models.Task) -> bool:
        if status_set is not None and task.status not in status_set:
            return False
        if prio_set is not None and task.priority not in prio_set:
            return False
        if tags_set is not None:
            task_tags_low = {t.lower() for t in task.tags}
            if task_tags_low.isdisjoint(tags_set):
                return False
        if start_date or end_date:
            if task.due_date is None:
                return False
            if start_date and task.due_date < start_date:
                return False
            if end_date and task.due_date > end_date:
                return False
        return True

    return [t for t in tasks if include(t)]
